-- AI Trust Assessment: trade_questions cache, worker_trust_assessments scores, users.trade_competency_score
--
-- Forward-only migration. Apply manually through the bastion after review.
--
-- Service role for AI Lambdas. Password is generated by CDK in `jale/ai/db`;
-- set it manually after this migration, matching the existing jale_matching pattern:
--   ALTER ROLE jale_ai WITH PASSWORD '<generated>';
DO $$
BEGIN
  CREATE ROLE jale_ai LOGIN;
EXCEPTION
  WHEN duplicate_object THEN
    RAISE NOTICE 'role jale_ai already exists, skipping CREATE ROLE';
END;
$$;

-- trade_questions -----------------------------------------------------------
CREATE TABLE trade_questions (
  id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  profession_key   TEXT        NOT NULL UNIQUE,
  profession_raw   TEXT        NOT NULL,
  questions        JSONB       NOT NULL,
  is_seeded        BOOLEAN     NOT NULL DEFAULT false,
  model_id         TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_trade_questions_profession_key ON trade_questions (profession_key);

GRANT SELECT, INSERT, UPDATE ON trade_questions TO jale_admin;
GRANT SELECT, INSERT, UPDATE ON trade_questions TO jale_ai;
GRANT SELECT ON trade_questions TO jale_whatsapp;

